22	const PROCESSING_FEE = 5;
23	const FIRST_INSURANCE_SURCHARGE = 0.1;
24	
25	/** Premiums round up — in the MHPCO's favour. Float noise is discarded first. */
26	const roundUpToWholeG = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));
27	
28	const BASE_PREMIUMS: Record<string, number> = {
29	  sword: 100,
30	  amulet: 60,
31	  staff: 80,
32	};
33	
34	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
35	
36	const quotePremium = (items: Item[]): number => {
37	  const policyBase = items.reduce((sum, item) => sum + basePremiumOf(item), 0);
38	  const withFirstInsurance = policyBase * (1 + FIRST_INSURANCE_SURCHARGE);
39	  const withProcessingFee = withFirstInsurance + PROCESSING_FEE;
40	  return roundUpToWholeG(withProcessingFee);
41	};
42	
43	export const runScenario = (scenario: Scenario): ScenarioResult => {
44	  return { results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })) };
45	};
